#include "ludcmp.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// Array initialization translated to Halide.
static
void init_array(int n,
                Halide::Buffer<num_t, 2> A,
                Halide::Buffer<num_t, 1> b,
                Halide::Buffer<num_t, 1> x,
                Halide::Buffer<num_t, 1> y) {
    Var i("i"), j("j");

    // Initialize x, y, b:
    // for (i = 0; i < n; i++) {
    //   x[i] = 0;
    //   y[i] = 0;
    //   b[i] = (i+1)/fn/2.0 + 4;
    // }
    Func init_x("init_x"), init_y("init_y"), init_b("init_b");

    Expr fn   = cast<num_t>(n);
    Expr two  = cast<num_t>(Expr(2.0));
    Expr four = cast<num_t>(Expr(4.0));

    init_x(i) = cast<num_t>(0);
    init_y(i) = cast<num_t>(0);
    init_b(i) = cast<num_t>(i + 1) / fn / two + four;

    init_x.realize(x);
    init_y.realize(y);
    init_b.realize(b);

    // Initialize A as a lower-triangular matrix with unit diagonal:
    //
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j <= i; j++)
    //       A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
    //   for (j = i+1; j < n; j++)
    //       A[i][j] = 0;
    //   A[i][i] = 1;
    // }
    //
    // Note: in C, A[i][j] is row i, column j.
    // In Halide::Buffer, we'll use A(j, i) (dim 0 = column j, dim 1 = row i).
    Func A_init("A_init");

    Expr row = i;
    Expr col = j;
    Expr nE  = Expr(n);
    Expr neg_mod = (-col) % nE;
    Expr tri_val = cast<num_t>(neg_mod) / cast<num_t>(nE) + cast<num_t>(1);

    A_init(j, i) =
        select(col > row,
               cast<num_t>(0),                                  // j > i -> 0
               select(col == row,
                      cast<num_t>(1),                           // j == i -> 1
                      tri_val));                                // j < i -> (-j % n)/n + 1

    // Make the matrix positive semi-definite (same as cholesky init):
    //
    // B[r][s] = sum_t A[r][t] * A[s][t];
    // A = B;
    //
    // Again, B(j, i) corresponds to B[i][j] in C.
    Func B_func("B");
    RDom t(0, n, "t");

    // B(j, i) = sum_{t} A_init[t][i] * A_init[t][j]
    //           = sum_t A_init(t, i) * A_init(t, j)
    B_func(j, i) = sum(A_init(t, i) * A_init(t, j));

    // Realize directly into the provided A buffer.
    B_func.realize(A);
}

// Main computational kernel translated to C++ using Halide::Buffer
// (data layout and semantics preserved).
static
void kernel_ludcmp(int n,
                   Halide::Buffer<num_t, 2> A,
                   Halide::Buffer<num_t, 1> b,
                   Halide::Buffer<num_t, 1> x,
                   Halide::Buffer<num_t, 1> y) {
    // Mapping note:
    //   Original C uses A[i][j]  (row i, column j).
    //   Here we store as A(j, i) (dim 0 = column j, dim 1 = row i).

    // LU factorization (no pivoting)
    for (int i = 0; i < n; i++) {
        // Compute L(i, j) for j < i
        for (int j = 0; j < i; j++) {
            num_t w = A(j, i); // A[i][j]

            for (int k = 0; k < j; k++) {
                // A[i][k] * A[k][j]
                w -= A(k, i) * A(j, k);
            }

            w /= A(j, j);       // divide by A[j][j]
            A(j, i) = w;        // A[i][j] = w
        }

        // Compute U(i, j) for j >= i
        for (int j = i; j < n; j++) {
            num_t w = A(j, i); // A[i][j]

            for (int k = 0; k < i; k++) {
                // A[i][k] * A[k][j]
                w -= A(k, i) * A(j, k);
            }

            A(j, i) = w;        // A[i][j] = w
        }
    }

    // Forward substitution: Ly = b
    for (int i = 0; i < n; i++) {
        num_t w = b(i);

        for (int j = 0; j < i; j++) {
            // A[i][j] * y[j]
            w -= A(j, i) * y(j);
        }

        y(i) = w;
    }

    // Backward substitution: Ux = y
    for (int i = n - 1; i >= 0; i--) {
        num_t w = y(i);

        for (int j = i + 1; j < n; j++) {
            // A[i][j] * x[j]
            w -= A(j, i) * x(j);
        }

        w /= A(i, i);  // divide by A[i][i]
        x(i) = w;
    }
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Buffers:
    // A: 2D, stored as A(j, i) => size (n columns, n rows)
    Halide::Buffer<num_t, 2> A(n, n);
    // b, x, y: 1D
    Halide::Buffer<num_t, 1> b(n), x(n), y(n);

    // Initialize arrays using Halide
    init_array(n, A, b, x, y);

    // Time the kernel (LU + forward + backward substitutions)
    auto start = std::chrono::high_resolution_clock::now();

    kernel_ludcmp(n, A, b, x, y);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result vector x (similar to PolyBench's print_array)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            std::cerr << x(i) << '\n';
        }
    }

    // Print timing (seconds)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
