#include <chrono>
#include <iomanip>
#include <iostream>
#include <utility>

#include "Halide.h"

// include common PolyBench-style definitions (N, DATA_TYPE, etc.)
#include "defines.hpp"

// include benchmark-specific definitions for ludcmp
#include "ludcmp.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// Initialize A, b, x, y the same way as the original C init_array().
static void init_array(int n,
                       Halide::Buffer<num_t, 2> A,  // logical A[i][j] accessed as A(j, i)
                       Halide::Buffer<num_t, 1> b,
                       Halide::Buffer<num_t, 1> x,
                       Halide::Buffer<num_t, 1> y) {
    Var i("i"), j("j");

    // Initialize x, y, b:
    //   x[i] = 0;
    //   y[i] = 0;
    //   b[i] = (i+1)/fn/2.0 + 4;   fn = (DATA_TYPE)n;
    {
        Func init_x("init_x"), init_y("init_y"), init_b("init_b");
        Expr fn = cast<num_t>(n);

        init_x(i) = cast<num_t>(0);
        init_y(i) = cast<num_t>(0);
        init_b(i) = cast<num_t>(i + 1) / (fn * cast<num_t>(2)) + cast<num_t>(4);

        init_x.realize(x);
        init_y.realize(y);
        init_b.realize(b);
    }

    // Initialize A as in the C code:
    //   for i in 0..n-1:
    //     for j in 0..i:   A[i][j] = (-j % n) / n + 1;
    //     for j in i+1..n-1: A[i][j] = 0;
    //     A[i][i] = 1;
    //
    // Then B = A * A^T, and A = B (positive semi-definite).
    {
        // First build the lower-triangular A with ones on the diagonal.
        Func A0("A0");

        // Remember: A0(j, i) corresponds to A[i][j].
        Expr lower_val = cast<num_t>(-(j % n)) / cast<num_t>(n) + cast<num_t>(1);
        A0(j, i) = select(j < i, lower_val,
                          select(j == i, cast<num_t>(1), cast<num_t>(0)));

        // Now compute B[r][s] = sum_t A[r][t] * A[s][t].
        // With our (x=j, y=i) layout, r -> row index, s -> row index:
        // B(s, r) = sum_t A0(t, r) * A0(t, s).
        RDom t(0, n, "t");
        Func B("B");
        B(j, i) = cast<num_t>(0);
        B(j, i) += A0(t, i) * A0(t, j);

        // Realize B into A; this overwrites A with the SPD matrix.
        B.realize(A);
    }
}

int main(int argc, char *argv[]) {
    // Problem size.
    int n = N;

    // Buffers:
    // A is n x n, but we store it as A(j, i) for C-style A[i][j].
    Halide::Buffer<num_t, 2> A(n, n);
    Halide::Buffer<num_t, 2> A_tmp(n, n);  // for double-buffering during LU
    Halide::Buffer<num_t, 1> b(n), x(n), y(n);

    // Initialize data.
    init_array(n, A, b, x, y);

    // ------------------------------------------------------------
    // Build a Halide pipeline that does one Doolittle LU step for a
    // given pivot index k. We maintain A in-place across steps via
    // double buffering, but each step itself is a pure transform
    // A_in -> A_out and does not read from its own output.
    //
    // This implements:
    //
    //   for (k = 0; k < n; k++) {
    //     for (i = k+1; i < n; i++)
    //       A[i][k] = A[i][k] / A[k][k];
    //     for (j = k+1; j < n; j++)
    //       for (i = k+1; i < n; i++)
    //         A[i][j] -= A[i][k] * A[k][j];
    //   }
    //
    // which is mathematically equivalent to the original algorithm.
    // ------------------------------------------------------------

    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    Param<int> k_param("k");

    Var x_var("x"), y_var("y");
    Var row("row");

    // L(row) = A[row][k] / A[k][k], i.e. L entries in column k.
    Func L("L");
    // A_param(x, y) is A[y][x] (row = y, col = x).
    L(row) = A_param(k_param, row) / A_param(k_param, k_param);

    // One LU step: given A_in (A_param) and pivot k, produce A_out.
    Func lud_step("lud_step");

    // Case analysis for A_out(i, j) with coordinates x=j, y=i:
    // 1) i > k && j == k: new L(i, k) = A[i][k] / A[k][k] = L(i)
    // 2) i > k && j > k:  A[i][j] -= L(i) * A[k][j]
    // 3) otherwise:       A[i][j] unchanged
    lud_step(x_var, y_var) =
        select(y_var > k_param && x_var == k_param,
               L(y_var),
               select(y_var > k_param && x_var > k_param,
                      A_param(x_var, y_var) - L(y_var) * A_param(x_var, k_param),
                      A_param(x_var, y_var)));

    // We use the default schedule here; JIT-compile once before timing.
    lud_step.compile_jit();

    // Double-buffering pointers for A during LU.
    Halide::Buffer<num_t, 2> *A_cur = &A;
    Halide::Buffer<num_t, 2> *A_next = &A_tmp;

    // ------------------------------------------------------------
    // Time the entire kernel: LU factorization + forward & back solve.
    // ------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    // LU factorization: apply n steps, updating A_cur each time.
    for (int k = 0; k < n; ++k) {
        A_param.set(*A_cur);
        k_param.set(k);
        lud_step.realize(*A_next);
        std::swap(A_cur, A_next);
    }

    // Ensure A holds the final factorization (optional but keeps semantics clear).
    if (A_cur != &A) {
        A.copy_from(*A_cur);
        A_cur = &A;
    }
    Halide::Buffer<num_t, 2> &A_fact = *A_cur;

    // Forward substitution: solve L * y = b.
    // Original code:
    //   for (i = 0; i < n; i++) {
    //     w = b[i];
    //     for (j = 0; j < i; j++)
    //       w -= A[i][j] * y[j];
    //     y[i] = w;
    //   }
    for (int i = 0; i < n; ++i) {
        num_t w = b(i);
        for (int j = 0; j < i; ++j) {
            // A[i][j] is A_fact(j, i) in our layout.
            w -= A_fact(j, i) * y(j);
        }
        y(i) = w;
    }

    // Back substitution: solve U * x = y.
    // Original code:
    //   for (i = n-1; i >= 0; i--) {
    //     w = y[i];
    //     for (j = i+1; j < n; j++)
    //       w -= A[i][j] * x[j];
    //     x[i] = w / A[i][i];
    //   }
    for (int i = n - 1; i >= 0; --i) {
        num_t w = y(i);
        for (int j = i + 1; j < n; ++j) {
            w -= A_fact(j, i) * x(j);  // A[i][j] == A_fact(j, i)
        }
        x(i) = w / A_fact(i, i);        // A[i][i] == A_fact(i, i)
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // ------------------------------------------------------------
    // Optionally print the result vector x (live-out data).
    // ------------------------------------------------------------
    if (argc > 1) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; ++i) {
            std::cerr << x(i) << '\n';
        }
    }

    // Print timing in seconds, like the example.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
