```c++
#include <chrono>
#include <iomanip>
#include <iostream>

#include "Halide.h"

// Common Polybench-style definitions (N, DATA_TYPE, etc.)
#include "defines.hpp"

// Benchmark-specific definitions (for ludcmp)
#include "ludcmp.hpp"

using num_t = DATA_TYPE;
using namespace Halide;

// -----------------------------------------------------------------------------
// Initialize arrays A, b, x, y using Halide, matching the original C init_array
// -----------------------------------------------------------------------------
static void init_array(int n,
                       Halide::Buffer<num_t, 2> A,  // shape (n, n), indexed as A(col, row) -> A[i][j]
                       Halide::Buffer<num_t, 1> b,  // shape (n)
                       Halide::Buffer<num_t, 1> x,  // shape (n)
                       Halide::Buffer<num_t, 1> y)  // shape (n)
{
    Var i("i"), col("col"), row("row");
    Expr n_i = Expr(n);
    Expr fn = cast<num_t>(n_i);
    Expr zero = cast<num_t>(Expr(0));
    Expr one  = cast<num_t>(Expr(1));
    Expr two  = cast<num_t>(Expr(2));
    Expr four = cast<num_t>(Expr(4));

    // x[i] = 0; y[i] = 0; b[i] = (i+1)/fn/2.0 + 4;
    Func init_x("init_x"), init_y("init_y"), init_b("init_b");

    init_x(i) = zero;
    init_y(i) = zero;

    {
        Expr idx = cast<num_t>(i + 1);
        // (i+1)/fn/2 + 4
        init_b(i) = (idx / fn) / two + four;
    }

    // Lower-triangular A with A[i][j] = (-j % n)/n + 1 for j <= i, 0 otherwise, then A[i][i] = 1.
    // We map A[i][j] -> A(col=j, row=i).
    Func tri_A("tri_A"), diag_A("diag_A");

    {
        Expr neg_col_mod_n = (-col) % n_i;      // (-j % n) in int32
        Expr val = cast<num_t>(neg_col_mod_n);  // cast to DATA_TYPE

        tri_A(col, row) =
            select(col <= row,
                   val / fn + one,  // (-j % n)/n + 1
                   zero);

        // Override diagonal: A[i][i] = 1
        diag_A(col, row) =
            select(col == row,
                   one,
                   tri_A(col, row));
    }

    // Make the matrix positive semi-definite:
    // B[r][s] = sum_t A[r][t] * A[s][t], then A = B.
    // In our mapping: B(col, row) corresponds to B[r][s],
    // A(row_index=r, col_index=t) -> diag_A(t, row),
    // A(row_index=s, col_index=t) -> diag_A(t, col).
    Func B_func("B_func");
    RDom t(0, n, "t");

    B_func(col, row) = zero;
    B_func(col, row) += diag_A(t, row) * diag_A(t, col);

    // Realize into the provided buffers.
    init_x.realize(x);
    init_y.realize(y);
    init_b.realize(b);
    B_func.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Buffers:
    // For 2D arrays A[i][j], map to Buffer with shape (n, n) and access A(j, i).
    Halide::Buffer<num_t, 2> A(n, n);  // (col, row)
    Halide::Buffer<num_t, 1> b(n);
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> y(n);

    // Initialize data using Halide
    init_array(n, A, b, x, y);

    // -----------------------
    // Halide kernels for LUD
    // -----------------------

    // ImageParams to wrap the Buffers
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam b_param(type_of<num_t>(), 1, "b_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");
    ImageParam y_param(type_of<num_t>(), 1, "y_param");

    // Scalar Params for indices and n
    Param<int> i_param("i");
    Param<int> j_param("j");
    Param<int> n_param("n");

    // Func to compute the numerator for L-part update:
    // w = A[i][j] - sum_{k=0}^{j-1} A[i][k] * A[k][j]
    // In our mapping: A[i][j] -> A_param(j, i), A[i][k] -> A_param(k, i), A[k][j] -> A_param(j, k).
    Func l_num("l_num");
    {
        RDom kL(0, j_param, "kL");
        l_num() = A_param(j_param, i_param);
        l_num() -= A_param(kL, i_param) * A_param(j_param, kL);
    }

    // Func to compute the numerator for U-part update:
    // w = A[i][j] - sum_{k=0}^{i-1} A[i][k] * A[k][j]
    Func u_num("u_num");
    {
        RDom kU(0, i_param, "kU");
        u_num() = A_param(j_param, i_param);
        u_num() -= A_param(kU, i_param) * A_param(j_param, kU);
    }

    // Func for forward substitution:
    // y[i] = b[i] - sum_{j=0}^{i-1} A[i][j] * y[j]
    // Mapping: A[i][j] -> A_param(j, i), y[j] -> y_param(j)
    Func forward_num("forward_num");
    {
        RDom rf(0, i_param, "rf");
        forward_num() = b_param(i_param);
        forward_num() -= A_param(rf, i_param) * y_param(rf);
    }

    // Func for backward substitution:
    // x[i] = (y[i] - sum_{j=i+1}^{n-1} A[i][j] * x[j]) / A[i][i]
    // We'll compute the numerator:
    // w = y[i] - sum_{j=i+1}^{n-1} A[i][j] * x[j]
    // Mapping: A[i][j] -> A_param(j, i), x[j] -> x_param(j)
    Func backward_num("backward_num");
    {
        RDom rb(i_param + 1, n_param - (i_param + 1), "rb");
        backward_num() = y_param(i_param);
        backward_num() -= A_param(rb, i_param) * x_param(rb);
    }

    // Bind buffers to ImageParams
    A_param.set(A);
    b_param.set(b);
    x_param.set(x);
    y_param.set(y);
    n_param.set(n);

    // JIT compile the small kernels once, outside the timed region
    Target target = get_jit_target_from_environment();
    l_num.compile_jit(target);
    u_num.compile_jit(target);
    forward_num.compile_jit(target);
    backward_num.compile_jit(target);

    // -----------------------------
    // Run the LUDCMP computation
    // -----------------------------
    auto start = std::chrono::high_resolution_clock::now();

    // LU factorization (in-place on A)
    for (int i = 0; i < n; i++) {
        // Compute L-part: j = 0 .. i-1
        if (i > 0) {
            for (int j = 0; j < i; j++) {
                num_t w;
                if (j == 0) {
                    // For j == 0, inner sum is empty: w = A[i][0]
                    // Mapping: A[i][0] -> A(0, i)
                    w = A(0, i);
                } else {
                    // Use Halide reduction for j > 0
                    i_param.set(i);
                    j_param.set(j);
                    Halide::Buffer<num_t> w_buf = l_num.realize({});
                    w = w_buf();
                }
                // A[i][j] = w / A[j][j]
                // Mapping: A[i][j] -> A(j, i), A[j][j] -> A(j, j)
                w = w / A(j, j);
                A(j, i) = w;
            }

            // Compute U-part: j = i .. n-1
            for (int j = i; j < n; j++) {
                // For i == 0, inner sum is empty and A[0][j] remains unchanged,
                // so we only need the reduction when i > 0.
                i_param.set(i);
                j_param.set(j);
                Halide::Buffer<num_t> w_buf = u_num.realize({});
                num_t w = w_buf();
                // A[i][j] = w
                A(j, i) = w;
            }
        } else {
            // i == 0: both L and U sums are empty.
            // The original code leaves row 0 unchanged for j >= 0, so nothing to do.
        }
    }

    // Forward substitution: solve L * y = b
    for (int i = 0; i < n; i++) {
        if (i == 0) {
            // y[0] = b[0]
            y(0) = b(0);
        } else {
            i_param.set(i);
            Halide::Buffer<num_t> w_buf = forward_num.realize({});
            num_t w = w_buf();
            y(i) = w;
        }
    }

    // Backward substitution: solve U * x = y
    for (int i = n - 1; i >= 0; i--) {
        num_t w;
        if (i == n - 1) {
            // x[n-1] = y[n-1] / A[n-1][n-1]
            w = y(i);
        } else {
            i_param.set(i);
            Halide::Buffer<num_t> w_buf = backward_num.realize({});
            w = w_buf();
        }
        // Divide by diagonal A[i][i]
        w = w / A(i, i);
        x(i) = w;
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optional: print the solution vector x if a command-line argument is given
    if (argc > 1) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            std::cerr << x(i) << '\n';
        }
    }

    // Print timing in seconds with 6 decimal places
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
